// Build AI forecast prompt with all signals
const sales = $('Fetch 12 Months Sales Data').item.json.body || $('Fetch 12 Months Sales Data').item.json;
const leads = $('Fetch 12 Months Lead Pipeline').item.json.body || $('Fetch 12 Months Lead Pipeline').item.json;
const distributors = $('Fetch Active Distributor Roster').item.json.body || $('Fetch Active Distributor Roster').item.json;

const salesData = sales.data || sales.monthly || [];
const leadData = leads.data || leads.leads || [];
const distData = distributors.data || distributors.distributors || [];

const totalSales12mo = salesData.reduce((s, m) => s + (m.totalSales || 0), 0);
const totalOrders12mo = salesData.reduce((s, m) => s + (m.totalOrders || 0), 0);
const tierCounts = distData.reduce((acc, d) => { acc[d.tier] = (acc[d.tier] || 0) + 1; return acc; }, {});

const prompt = `You are a sales forecasting analyst. Generate a 4-week forward forecast based on the following data.

Return JSON with this schema:
{
  "forecast": [
    { "week": "YYYY-MM-DD", "projectedRevenue": int, "projectedOrders": int, "confidence": 0-100 }
  ],
  "insights": ["string", ...],
  "risks": ["string", ...],
  "recommendations": ["string", ...],
  "assumptions": ["string", ...]
}

Historical monthly sales (last 12 months):
${JSON.stringify(salesData, null, 2)}

Active lead pipeline (last 12 months, by status):
${JSON.stringify(leadData.reduce((acc, l) => { acc[l.status] = (acc[l.status] || 0) + 1; return acc; }, {}))}

Distributor roster:
- Total active: ${distData.length}
- Tier distribution: ${JSON.stringify(tierCounts)}

12-month totals: revenue=${totalSales12mo}, orders=${totalOrders12mo}`;

return [{
  json: {
    forecastDate: new Date().toISOString(),
    horizonWeeks: 4,
    inputData: {
      monthlySales: salesData,
      leadPipelineCounts: leadData.reduce((acc, l) => { acc[l.status] = (acc[l.status] || 0) + 1; return acc; }, {}),
      distributorCount: distData.length,
      tierCounts
    },
    prompt
  }
}];

const resp = $json.body || $json;
let forecast = { forecast: [], insights: [], risks: [], recommendations: [], assumptions: [] };
try {
  let parsed = typeof resp === 'string' ? JSON.parse(resp) : resp;
  if (parsed.data) parsed = parsed.data;
  if (parsed.content) parsed = typeof parsed.content === 'string' ? JSON.parse(parsed.content) : parsed.content;
  forecast = {
    forecast: Array.isArray(parsed.forecast) ? parsed.forecast : [],
    insights: Array.isArray(parsed.insights) ? parsed.insights : [],
    risks: Array.isArray(parsed.risks) ? parsed.risks : [],
    recommendations: Array.isArray(parsed.recommendations) ? parsed.recommendations : [],
    assumptions: Array.isArray(parsed.assumptions) ? parsed.assumptions : []
  };
} catch (e) { /* defaults */ }

const totalProjected = forecast.forecast.reduce((s, f) => s + (f.projectedRevenue || 0), 0);
const totalProjectedOrders = forecast.forecast.reduce((s, f) => s + (f.projectedOrders || 0), 0);

return [{
  json: {
    forecastDate: $('Build Forecast Prompt').item.json.forecastDate,
    horizonWeeks: 4,
    inputData: $('Build Forecast Prompt').item.json.inputData,
    forecast: forecast.forecast,
    insights: forecast.insights,
    risks: forecast.risks,
    recommendations: forecast.recommendations,
    assumptions: forecast.assumptions,
    summary: {
      totalProjectedRevenue: totalProjected,
      totalProjectedOrders: totalProjectedOrders,
      weekCount: forecast.forecast.length
    }
  }
}];
